 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B2/",P=A+"Props/B2/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_Cooling/";
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
