 public static object Detail(){var s=Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).ToDictionary(m=>m.name);
 var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/BC_Display_10.png");if(tex){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="BCM_Display_10"};m.SetTexture("_BaseMap",tex);m.SetFloat("_Smoothness",.2f);AssetDatabase.CreateAsset(m,E+"Materials/"+m.name+".mat");mats[m.name]=m;}
 foreach(string path in new[]{E+"BC_ServiceLightSupports.fbx",P+"BC_WallSafety_R11.fbx",E+"BC_CoolingPipework.fbx"}){var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"B4O_"+kv.Key.Substring(4)),kv.Value);mi.SaveAndReimport();}
 var root=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform;var lighting=root.Find("Lighting");if(lighting.Find("B2_C02_ServiceLightSupports"))throw new Exception("Already detailed");Put("B2_C02_ServiceLightSupports",E+"BC_ServiceLightSupports.fbx",lighting,Vector3.zero);
 int i=0;foreach(var v in new[]{new Vector3(-8.65f,2.48f,2.65f),new Vector3(3.05f,2.88f,7.25f),new Vector3(0,2.88f,7.2f)}){var g=Put("B2_C02_LocalTaskLight_"+(++i),A+"Environment/B4/BO_SealedTaskLight.fbx",lighting,v);var c=new GameObject("LightSource").AddComponent<Light>();c.transform.SetParent(g.transform,false);c.transform.localPosition=new Vector3(0,-.1f,0);c.transform.localRotation=Quaternion.Euler(90,0,0);c.type=LightType.Spot;c.color=new Color(.90f,.92f,.94f);c.intensity=3.4f;c.range=4.8f;c.spotAngle=110;c.innerSpotAngle=78;c.shadows=LightShadows.Soft;c.shadowBias=.008f;c.shadowNormalBias=.012f;}
 float a=145*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));float face=Mathf.Sqrt(121-2.13f*2.13f)-.20f;var safety=Put("B2_C02_WallSafety_01",P+"BC_WallSafety_R11.fbx",root.Find("Equipment"),dir*face,Quaternion.LookRotation(-dir).eulerAngles.y);var bc=safety.AddComponent<BoxCollider>();bc.center=new Vector3(0,1.10f,.20f);bc.size=new Vector3(1.34f,1.75f,.42f);
