 public static object Probes(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform;var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf;player.SetActive(false);try{int i=0;foreach(var pos in new[]{new Vector3(0,2,0),new Vector3(0,5.1f,4.5f)}){var g=new GameObject("B2_C02_Reflection_"+(++i));g.transform.SetParent(root,false);g.transform.localPosition=pos;var p=g.AddComponent<ReflectionProbe>();p.size=i==1?new Vector3(22,6.6f,22):new Vector3(16,6,10);p.center=i==1?Vector3.zero:new Vector3(0,1,-1);p.importance=i;p.blendDistance=1.2f;p.resolution=128;p.hdr=true;p.boxProjection=true;p.mode=ReflectionProbeMode.Custom;p.renderDynamicObjects=true;p.clearFlags=ReflectionProbeClearFlags.SolidColor;p.backgroundColor=new Color(.05f,.06f,.07f);p.intensity=.85f;string file=E+"Textures/BC_Reflection_"+i+".exr";if(!Lightmapping.BakeReflectionProbe(p,file))throw new Exception("Reflection failed");AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(file);}}finally{player.SetActive(active);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{probes=2};}
 public static object LodPlan(){var s=Check();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>()).Where(r=>r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh&&r.GetComponent<MeshFilter>().sharedMesh.isReadable&&!r.GetComponentInParent<LODGroup>()).ToArray();var groups=all.Where(r=>r.GetComponent<MeshFilter>().sharedMesh.name.Contains("ReactorTank")||AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh).StartsWith(P+"BC_")).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh);int n=0;var plan=new List<object>();foreach(var group in groups){var m=group.Key;var r=group.First();plan.Add(new{name="BC_Lod_"+(++n).ToString("00"),asset=AssetDatabase.GetAssetPath(m),tri=m.triangles.Length/3,renderers=group.Select(r=>GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()).ToArray(),materials=r.sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray()});}File.WriteAllText(H+"lod_plan.json",JsonConvert.SerializeObject(plan,Formatting.Indented));return new{models=n};}
 public static object CCTV(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B2_C02_CoolingSector").transform;var eq=root.Find("Equipment");if(eq.Find("B2_C02_CCTV"))throw new Exception("Already installed");float a=-30*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var mount=Put("B2_C02_CCTVWallMount",A+"Environment/B3/BS_CCTVWallMount_R11.fbx",eq,dir*(Mathf.Sqrt(121-3.65f*3.65f)-.16f),Quaternion.LookRotation(-dir).eulerAngles.y);var camera=Put("B2_C02_CCTV",A+"Enemy/CCTV_SecurityCamera_Articulated.prefab",eq,Vector3.zero);camera.transform.SetPositionAndRotation(mount.transform.TransformPoint(new Vector3(0,3.287f,.49f)),mount.transform.rotation);PrefabUtility.RecordPrefabInstancePropertyModifications(camera.transform);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{cameras=1,scriptsAdded=0};}
